import pandas as pd

def get_turn_scores(rolls):
    scores = [0] * 6
    m = max(rolls)
    scores[0] = m * rolls.count(m)
    scores[1] = sum(rolls)
    hi = max(rolls)
    lo = min(rolls)
    scores[2] = hi * lo * (hi - lo)
    if len(set(rolls)) <= 2:
        scores[3] = 30
    if sorted(rolls) == [1, 2, 3, 4, 5, 6]:
        scores[4] = 40
    has_subset = False
    for i in range(len(rolls) - 3):
        sub = rolls[i:i+4]
        if sub[1] == sub[0] + 1 and sub[2] == sub[1] + 1 and sub[3] == sub[2] + 1:
            has_subset = True
            break
        if sub[1] == sub[0] - 1 and sub[2] == sub[1] - 1 and sub[3] == sub[2] - 1:
            has_subset = True
            break
    if has_subset:
        scores[5] = 50
    return scores

def solve():
    df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=None, skiprows=9)

    turns_data = {}

    def process_row(turn_col, game_col, roll_start_col, row):
        try:
            if pd.isna(row[turn_col]) or pd.isna(row[game_col]):
                return
            t_num = int(row[turn_col])
            g_num = int(row[game_col])
            rolls = [int(row[i]) for i in range(roll_start_col, roll_start_col + 6)]
            turns_data[t_num] = {
                'game': g_num,
                'scores': get_turn_scores(rolls)
            }
        except:
            pass

    for _, row in df.iterrows():
        # Regular columns
        process_row(2, 3, 4, row)
        # Alternate columns (from our discovery)
        process_row(13, 14, 15, row)

    games = {}
    for t_num in sorted(turns_data.keys()):
        data = turns_data[t_num]
        g = data['game']
        if g not in games:
            games[g] = []
        games[g].append(data['scores'])

    print(f"Turns found: {len(turns_data)}")
    print(f"Games found: {len(games)}")

    game_scores = {}
    for g, turn_scores_list in games.items():
        if len(turn_scores_list) != 2:
            continue
        s1, s2 = turn_scores_list[0], turn_scores_list[1]
        max_game_score = 0
        for i in range(6):
            for j in range(6):
                if i != j:
                    combined = s1[i] + s2[j]
                    if combined > max_game_score:
                        max_game_score = combined
        game_scores[g] = max_game_score

    p1_wins = 0
    p2_wins = 0
    for k in range(1, 1501):
        g1, g2 = 2*k - 1, 2*k
        s1, s2 = game_scores.get(g1), game_scores.get(g2)
        if s1 is not None and s2 is not None:
            if s1 > s2:
                p1_wins += 1
            elif s2 > s1:
                p2_wins += 1
    print(f"Result: {p1_wins - p2_wins}")

if __name__ == "__main__":
    solve()
